window.DOSIK=window.DOSIK||{};DOSIK["kb_otsu4_sei"]={"1":[{"t":"tree","title":"第4類の共通性状","root":"危険物と第4類の共通性状","branches":[["状態","常温（20℃）で、ほとんどのものが液状である。 · すべての危険物は、1気圧、20℃で固体又は液体である。"],["燃え方","引火して炎を上げて燃える。 · 燃焼範囲は下限界と上限界を持つ。 · 可燃性の蒸気は、空気と一定範囲の混合割合でなければ燃焼しない。"],["静電気","電気の不良導体で、静電気が蓄積されやすく、静電気の火花により引火することがある。"],["水・沸点","水に溶けないものが多い。 · 沸点が水より高いものがある。"],["酸素","危険物には酸素を含有し酸素供給が無くても燃焼するものがある。"]]},{"t":"cause","title":"引火の危険性","causes":["引火点が低い物質ほど高く、引火点の高い物質ほど低い。","引火点の低いものほど、引火の危険性が大きい。"],"result":"引火の危険性","effects":["発火点が100℃以下のものもある。"]}],"2":[{"t":"tree","title":"特殊引火物","root":"特殊引火物","branches":[["外観","無色透明の液体である。"],["危険","引火点が非常に低く、引火、爆発の危険がある。"],["分解","熱、光により分解し、メタン、一酸化炭素を発生する。"],["過酸化物","空気と接触し加圧すると、爆発性の過酸化物を生成することがある。"]]}],"3":[{"t":"tree","title":"第一石油類","root":"第一石油類","branches":[["外観","いずれも無色の液体で、水より軽い。"],["成分","いずれも芳香族炭化水素である。"],["引火点","いずれも引火点は常温（20℃）より低い。"],["蒸気","蒸気は共に有毒である。 · 蒸気は空気より重く、低所に滞留しやすい。"]]}],"4":[{"t":"table","title":"アルコール類","head":["項目","比較"],"rows":[["蒸気比重","2-プロパノールのほうが大きい。"],["沸点","2-プロパノールのほうが高い。"],["燃焼範囲","メタノールの方が広い。 · どちらもガソリンより広い。"],["火災時","ともに水溶性液体用泡消火剤が有効である。"]]}],"5":[{"t":"tree","title":"第二石油類","root":"第二石油類","branches":[["重合","重合しやすく、重合熱が大きいので発火・爆発のおそれがある。"],["水溶液","水溶液は金属を強く腐食する。"]]}],"6":[{"t":"tree","title":"第三石油類","root":"第三石油類","branches":[["区分","A重油、B重油、C重油に分かれており、さらに細分化されている。"],["引火点","引火点は重油の種類によって異なる。"],["成分","主な成分は炭化水素だが硫黄などが含まれている。"],["火災時","火災時には散水は不向きである。"]]}],"7":[{"t":"tree","title":"第四石油類","root":"第四石油類","branches":[["種類","潤滑油や可塑剤など、多くの種類がある。"],["状態","1気圧において、温度20℃で液状である。"],["引火点","引火点が200℃以上250℃未満と高く、加熱しない限り引火の危険性はない。"],["揮発性","常温では蒸発しにくい。 · 揮発性がほとんどなく、蒸発しにくい。"],["水","水に溶けず粘度が高い。 · 水に溶けず、水より軽いものが多い。"],["火災時","火災になった場合は液温が高くなり消火が困難となる。"]]}],"8":[{"t":"tree","title":"動植物油類","root":"動植物油類","branches":[["定義","動植物から抽出した引火点が250℃未満の油類である。"],["危険性","ヨウ素価という値によって危険性が異なる。"],["性質","比重が水より小さく水に溶けない。"],["引火","常温での引火性は低い。"],["自然発火","染み込んだ油が空気中の酸素で酸化され熱が溜まるため。"]]}],"9":[{"t":"tree","title":"貯蔵・取扱い上の注意","root":"火災予防の方法","branches":[["小分け・取扱い","容器等に小分け作業をする場合は、蒸気及びミストを発散させないようにする。 · 空き缶であっても、残存する蒸気があると考えられるので注意して取り扱った。 · 引火しないように、火気の使用を控えた。"],["静電気","タンク、容器、配管、ノズル等 · できる限り導電性のもの使用し、導体部分は接地する。 · 水を散布するなどして周囲の湿度を上げる。"],["換気","十分な通風と換気を行い、可燃性蒸気の滞留を抑制する。蒸気は低所に滞留しやすい。 · 危険物の蒸気を排出する設備の吸気口の位置は、床面近く · 排気口は屋外の高所とする。"],["冷却・乾燥","タンク内の液温が上がらないよう、冷却のための装置を設けた。 · 危険物が塗布されたものを乾燥する場合 · 蒸気や温水を利用した温風乾燥機を使用する。"],["漏えい","危険物を取り扱う設備や配管のフランジなどから、危険物のにじみがないか確認する。 · 危険物を取り扱う設備の周囲に溝を設け · 流出した危険物を安全な位置に設置された処理槽まで導くなどの対策を行う。"]]}],"10":[{"t":"table","title":"火災と消火設備","head":["火災","消火"],"rows":[["ベンゼン","リン酸塩類等の粉末消火器は効果がある。"],["トルエン","ハロゲン化物消火器は効果がある。"],["灯油","棒状注水するのは効果がない。 · 水により火面が拡大してしまうため。"],["重油","泡消火器は効果がある。"]]},{"t":"tree","title":"適応する消火剤","root":"消火剤","branches":[["泡消火剤","泡消火剤は有効である。水溶性液体の火災には水溶性液体用を使用する。 · 他の泡消火剤に比べ、泡が溶解したり、破壊されることがないから"],["二酸化炭素","二酸化炭素消火剤は有効である。"],["粉末","粉末消火剤は有効である。"],["ハロゲン化物","ハロゲン化物消火剤は有効である。 · ハロゲン化物消火剤は効果的である。"],["棒状の水","棒状の水は効果的ではない。"]]}],"11":[{"t":"tree","title":"固定給油設備の点検","root":"固定給油設備の点検","branches":[["前面カバー","固定給油設備は定期的に前面カバーを取り外す · ポンプ及び配管に漏れがないか点検する。"],["給油中","給油中は吐出状況を監視し、ノズルから空気（気泡）を吹き出していないか注意する。"],["油ごみ","固定給油設備のポンプ及び配管等の一部に著しく油ごみ等が付着する場合 · その付近に漏れの疑いがある · 重点的に点検する。"],["清掃","固定給油設備のポンプ周囲及び下部ピット内 · 点検を容易にするため常に清掃しておく。"]]}]};
